#!/usr/bin/env python3
import pdfplumber
import json
import os
import re

input_dir = "/environment/input_artifacts/"

# Get all PDF files
pdf_files = sorted([f for f in os.listdir(input_dir) if f.endswith('.pdf')])
print(f"Found {len(pdf_files)} PDF files")

# Store extracted data for each PDF
all_data = {}

for pdf_file in pdf_files:
    filepath = os.path.join(input_dir, pdf_file)
    print(f"\nProcessing: {pdf_file}")

    try:
        with pdfplumber.open(filepath) as pdf:
            text_content = []
            toc_pages = []

            # Only extract from first 50 pages to save time
            max_pages = min(len(pdf.pages), 50)
            for i in range(max_pages):
                text = pdf.pages[i].extract_text()
                if text:
                    text_content.append(text.lower())

            full_text = "\n".join(text_content)

            # Store the data
            all_data[pdf_file] = {
                'text': full_text,
                'pages': len(pdf.pages)
            }

            print(f"  Pages processed: {max_pages}/{len(pdf.pages)}, Text: {len(full_text)} chars")

    except Exception as e:
        print(f"  Error: {e}")
        all_data[pdf_file] = {'text': '', 'pages': 0}

# Save raw data
with open('/workspace/raw_text_data.json', 'w') as f:
    save_data = {k: {'text': v['text'][:10000], 'pages': v['pages']} 
                 for k, v in all_data.items()}
    json.dump(save_data, f, indent=2)

print(f"\n\nExtraction complete. Processed {len(all_data)} PDFs.")

