import pdfplumber
import re

input_dir = '/environment/input_artifacts/'

# Check 646717.pdf for TOC
pdf_file = '646717.pdf'
filepath = input_dir + pdf_file

with pdfplumber.open(filepath) as pdf:
    for i in range(min(20, len(pdf.pages))):
        try:
            text = pdf.pages[i].extract_text()
            if text:
                text_lower = text.lower()
                lines = text_lower.split('\\n')
                for line in lines:
                    if any(k in line for k in ['contents', 'chapter', 'dying', 'happiness', 'falling', 'hal', 'afterword', 'bibliography']):
                        nums = re.findall(r'(\d+)', line.strip())
                        if nums:
                            print(f'Page {i+1}: {line.strip()}')
        except:
            pass
